param([Parameter(Mandatory=$true)][string]$Destination,[string]$EnvironmentFile='.env.staging')
$ErrorActionPreference='Stop';$project=Split-Path -Parent $PSScriptRoot;$resolvedDestination=[IO.Path]::GetFullPath($Destination);New-Item -ItemType Directory -Force -Path $resolvedDestination|Out-Null;$settings=@{};Get-Content -LiteralPath (Join-Path $project $EnvironmentFile)|ForEach-Object{if($_-match'^\s*([^#=]+)=(.*)$'){$settings[$matches[1].Trim()]=$matches[2].Trim()}};$url=$settings['DATABASE_ADMIN_URL'];if(-not$url){throw 'DATABASE_ADMIN_URL is missing'};$pgDump=Join-Path $project '.runtime\postgresql\pgsql\bin\pg_dump.exe';$pgRestore=Join-Path $project '.runtime\postgresql\pgsql\bin\pg_restore.exe';if(-not(Test-Path -LiteralPath $pgDump)){throw 'PostgreSQL backup tools are missing'};$stamp=Get-Date -Format'yyyyMMdd-HHmmss';$dump=Join-Path $resolvedDestination "warevanta-staging-$stamp.dump";&$pgDump --format=custom --no-owner --file=$dump --dbname=$url;if($LASTEXITCODE){throw 'Managed database backup failed'};&$pgRestore --list $dump|Out-Null;if($LASTEXITCODE){throw 'Backup archive verification failed'};$hash=(Get-FileHash -Algorithm SHA256 -LiteralPath $dump).Hash.ToLowerInvariant();Set-Content -LiteralPath "$dump.sha256" -Value "$hash  $([IO.Path]::GetFileName($dump))";Write-Output "Verified managed backup created: $dump"
